-- ============================================================================
-- Migration 1098: the Part Assembly machines -- the specs their calculators read, the robotic spot welders' crew, and India
-- ============================================================================
-- Generated by scripts/generate-part-assembly-machines-migration.js; re-run it and diff instead of editing.
--
-- Part Assembly (memory/Part Assembly: welded parts) had its 25 machines in HR Rates for the USA only (migration 795), and the welders
-- were unusable:
--   * no specs: migration 864 wrote the welders' parameters by class name, but migration 827 had already renamed the classes to
--     part_assembly_*, so 864 matched none of them. Here each welder gets the specs its calculator reads (migration 1100), by key: from its
--     USA machine file, and the values that file does not have (manual MIG: wire diameter, weld density, tack pitch; robotic MIG: wire feed
--     rate) from the machine's row of memory/Countries data/India_XML_Data_.csv, the machine's own parameters (the same in every country export).
--   * the robotic spot welders' crew is 0.10 operators in memory; it was inserted as 0 (a smallint column then, migration 971 widened it),
--     so their labour was costed at nothing.
--   * the laser seam welder's Index Time is given with no unit (beside Load Time 30 s and Unload Time 15 s): kept as index_time_s, seconds.
--   * the wire brushing speed is added under the key its calculator reads.
--
-- India: memory/Countries data/India_XML_Data_.csv, commodity "Part Assembly" (25 machines): each machine's direct and indirect overhead (USD/hr, to
-- cents) on its USA twin (same class, exact name; "PerformArc 52 (Pansonic)" in the export is HR Rates' "PerformArc 52 (Panasonic)").
-- Labour: the India rate of the process's wage grade (memory/Part Assembly/wage_grade_associations_welding_group.csv), the rate the India
-- rows of that grade carry (2 - Metal 1.65, 5 - Metal 2.75, 6 - Metal 3.52 USD/hr), as migration 1075 did for Assembly.
--   Bevel Cutting           1 machine(s)
--   Finish Grinding         1 machine(s)
--   Grinding                1 machine(s)
--   Laser Seam Welding      1 machine(s)
--   Manual MIG Welding      5 machine(s)
--   Manual Spot Welding     5 machine(s)
--   Robotic MIG Welding     5 machine(s)
--   Robotic Spot Welding    5 machine(s)
--   Wire Brushing           1 machine(s)
--
-- Idempotent. Verify:
--   SELECT location, machine_class, count(*), count(*) FILTER (WHERE specs ? 'gun_placement_time_s') FROM mhr_records
--    WHERE process_group = 'Part Assembly' GROUP BY 1, 2 ORDER BY 1, 2;
-- ============================================================================

UPDATE mhr_records m
SET specs = COALESCE(m.specs, '{}'::jsonb) || v.specs,
    operators = COALESCE(v.operators, m.operators),
    updated_at = now()
FROM (VALUES
  ($str$part_assembly_manual_mig_welding$str$, $str$C240 (ESAB- 20A to 220A)$str$, $jsonb${"source":"memory/Part Assembly/Machine/manual_mig_weld_machines.csv","wire_feed_rate_mm_s":212,"arc_time_std":1.32,"gun_clean_time_per_arc_s":0.05,"gun_placement_time_s":2,"tack_length_mm":6,"wire_cost_usd_per_kg":1.85,"wire_diameter_mm":1.321,"weld_density_kg_per_m3":7803,"tack_pitch_mm":100,"source_export":"wire_diameter_mm, weld_density_kg_per_m3, tack_pitch_mm: memory/Countries data/India_XML_Data_.csv, the machine's row"}$jsonb$::jsonb, NULL::numeric),
  ($str$part_assembly_manual_mig_welding$str$, $str$C280 (ESAB- 30A to 280A)$str$, $jsonb${"source":"memory/Part Assembly/Machine/manual_mig_weld_machines.csv","wire_feed_rate_mm_s":275,"arc_time_std":1.32,"gun_clean_time_per_arc_s":0.05,"gun_placement_time_s":2,"tack_length_mm":6,"wire_cost_usd_per_kg":1.85,"wire_diameter_mm":1.6,"weld_density_kg_per_m3":7803,"tack_pitch_mm":100,"source_export":"wire_diameter_mm, weld_density_kg_per_m3, tack_pitch_mm: memory/Countries data/India_XML_Data_.csv, the machine's row"}$jsonb$::jsonb, NULL::numeric),
  ($str$part_assembly_manual_mig_welding$str$, $str$C420 (ESAB- 50A to 420A)$str$, $jsonb${"source":"memory/Part Assembly/Machine/manual_mig_weld_machines.csv","wire_feed_rate_mm_s":190,"arc_time_std":1.32,"gun_clean_time_per_arc_s":0.05,"gun_placement_time_s":2,"tack_length_mm":6,"wire_cost_usd_per_kg":1.85,"wire_diameter_mm":0.889,"weld_density_kg_per_m3":7803,"tack_pitch_mm":100,"source_export":"wire_diameter_mm, weld_density_kg_per_m3, tack_pitch_mm: memory/Countries data/India_XML_Data_.csv, the machine's row"}$jsonb$::jsonb, NULL::numeric),
  ($str$part_assembly_manual_mig_welding$str$, $str$Default Mig Weld$str$, $jsonb${"source":"memory/Part Assembly/Machine/manual_mig_weld_machines.csv","wire_feed_rate_mm_s":148,"arc_time_std":1.32,"gun_clean_time_per_arc_s":0.05,"gun_placement_time_s":2,"tack_length_mm":6,"wire_cost_usd_per_kg":1.85,"wire_diameter_mm":1.143,"weld_density_kg_per_m3":7803,"tack_pitch_mm":100,"source_export":"wire_diameter_mm, weld_density_kg_per_m3, tack_pitch_mm: memory/Countries data/India_XML_Data_.csv, the machine's row"}$jsonb$::jsonb, NULL::numeric),
  ($str$part_assembly_manual_mig_welding$str$, $str$Deltaweld 653 (Miller)$str$, $jsonb${"source":"memory/Part Assembly/Machine/manual_mig_weld_machines.csv","wire_feed_rate_mm_s":212,"arc_time_std":1.32,"gun_clean_time_per_arc_s":0.05,"gun_placement_time_s":2,"tack_length_mm":6,"wire_cost_usd_per_kg":1.85,"wire_diameter_mm":1.143,"weld_density_kg_per_m3":7803,"tack_pitch_mm":100,"source_export":"wire_diameter_mm, weld_density_kg_per_m3, tack_pitch_mm: memory/Countries data/India_XML_Data_.csv, the machine's row"}$jsonb$::jsonb, NULL::numeric),
  ($str$part_assembly_robotic_mig_welding$str$, $str$Default Robotic Mig$str$, $jsonb${"source":"memory/Part Assembly/Machine/robotic_mig_weld_machines.csv","arc_time_std":1.05,"gun_clean_time_per_arc_s":0.05,"gun_placement_time_s":2,"programming_time_per_weld_s":300,"weld_heads":1,"tack_length_mm":6,"tack_pitch_mm":100,"weld_density_kg_per_m3":7803,"wire_diameter_mm":1.14,"wire_cost_usd_per_kg":1.85,"wire_feed_rate_mm_s":212,"source_export":"wire_feed_rate_mm_s: memory/Countries data/India_XML_Data_.csv, the machine's row"}$jsonb$::jsonb, NULL::numeric),
  ($str$part_assembly_robotic_mig_welding$str$, $str$Pro System 2000 (Pro-Robots)$str$, $jsonb${"source":"memory/Part Assembly/Machine/robotic_mig_weld_machines.csv","arc_time_std":1.05,"gun_clean_time_per_arc_s":0.05,"gun_placement_time_s":2,"programming_time_per_weld_s":300,"weld_heads":1,"tack_length_mm":6,"tack_pitch_mm":100,"weld_density_kg_per_m3":7803,"wire_diameter_mm":1.6,"wire_cost_usd_per_kg":1.85,"wire_feed_rate_mm_s":275,"source_export":"wire_feed_rate_mm_s: memory/Countries data/India_XML_Data_.csv, the machine's row"}$jsonb$::jsonb, NULL::numeric),
  ($str$part_assembly_robotic_mig_welding$str$, $str$Pro System 3000 (Pro-Robots)$str$, $jsonb${"source":"memory/Part Assembly/Machine/robotic_mig_weld_machines.csv","arc_time_std":1.05,"gun_clean_time_per_arc_s":0.05,"gun_placement_time_s":2,"programming_time_per_weld_s":300,"weld_heads":1,"tack_length_mm":6,"tack_pitch_mm":100,"weld_density_kg_per_m3":7803,"wire_diameter_mm":1.32,"wire_cost_usd_per_kg":1.85,"wire_feed_rate_mm_s":212,"source_export":"wire_feed_rate_mm_s: memory/Countries data/India_XML_Data_.csv, the machine's row"}$jsonb$::jsonb, NULL::numeric),
  ($str$part_assembly_robotic_mig_welding$str$, $str$Pro Systen 1200$str$, $jsonb${"source":"memory/Part Assembly/Machine/robotic_mig_weld_machines.csv","arc_time_std":1.05,"gun_clean_time_per_arc_s":0.05,"gun_placement_time_s":2,"programming_time_per_weld_s":300,"weld_heads":1,"tack_length_mm":6,"tack_pitch_mm":100,"weld_density_kg_per_m3":7803,"wire_diameter_mm":1.14,"wire_cost_usd_per_kg":1.85,"wire_feed_rate_mm_s":148,"source_export":"wire_feed_rate_mm_s: memory/Countries data/India_XML_Data_.csv, the machine's row"}$jsonb$::jsonb, NULL::numeric),
  ($str$part_assembly_robotic_mig_welding$str$, $str$Twin Station (ICS Robotics)$str$, $jsonb${"source":"memory/Part Assembly/Machine/robotic_mig_weld_machines.csv","arc_time_std":1.05,"gun_clean_time_per_arc_s":0.05,"gun_placement_time_s":2,"programming_time_per_weld_s":300,"weld_heads":1,"tack_length_mm":6,"tack_pitch_mm":100,"weld_density_kg_per_m3":7803,"wire_diameter_mm":0.89,"wire_cost_usd_per_kg":1.85,"wire_feed_rate_mm_s":190,"source_export":"wire_feed_rate_mm_s: memory/Countries data/India_XML_Data_.csv, the machine's row"}$jsonb$::jsonb, NULL::numeric),
  ($str$part_assembly_manual_spot_welding$str$, $str$Default Spot Weld$str$, $jsonb${"source":"memory/Part Assembly/Machine/manual_spot_weld_machines.csv","gun_clean_time_per_arc_s":0,"gun_placement_time_s":2,"spot_weld_time_s":0.96}$jsonb$::jsonb, NULL::numeric),
  ($str$part_assembly_manual_spot_welding$str$, $str$LMSW (Miller- 152mm tongs)$str$, $jsonb${"source":"memory/Part Assembly/Machine/manual_spot_weld_machines.csv","gun_clean_time_per_arc_s":0,"gun_placement_time_s":2,"spot_weld_time_s":0.96}$jsonb$::jsonb, NULL::numeric),
  ($str$part_assembly_manual_spot_welding$str$, $str$MSW (Miller- 152 mm tongs)$str$, $jsonb${"source":"memory/Part Assembly/Machine/manual_spot_weld_machines.csv","gun_clean_time_per_arc_s":0,"gun_placement_time_s":2,"spot_weld_time_s":0.96}$jsonb$::jsonb, NULL::numeric),
  ($str$part_assembly_manual_spot_welding$str$, $str$SSW (Miller- 152 mm tongs)$str$, $jsonb${"source":"memory/Part Assembly/Machine/manual_spot_weld_machines.csv","gun_clean_time_per_arc_s":0,"gun_placement_time_s":2,"spot_weld_time_s":0.96}$jsonb$::jsonb, NULL::numeric),
  ($str$part_assembly_manual_spot_welding$str$, $str$SSW (Miller- 305 mm tongs)$str$, $jsonb${"source":"memory/Part Assembly/Machine/manual_spot_weld_machines.csv","gun_clean_time_per_arc_s":0,"gun_placement_time_s":2,"spot_weld_time_s":0.96}$jsonb$::jsonb, NULL::numeric),
  ($str$part_assembly_robotic_spot_welding$str$, $str$Default Robotic Spot$str$, $jsonb${"source":"memory/Part Assembly/Machine/robotic_spot_weld_machines.csv","gun_clean_time_per_arc_s":0,"gun_placement_time_s":2,"programming_time_per_weld_s":300,"spot_weld_time_s":0.96,"weld_heads":1}$jsonb$::jsonb, 0.1::numeric),
  ($str$part_assembly_robotic_spot_welding$str$, $str$PerformArc 100 (Pansonic- 60'' Turntable)$str$, $jsonb${"source":"memory/Part Assembly/Machine/robotic_spot_weld_machines.csv","gun_clean_time_per_arc_s":0,"gun_placement_time_s":2,"programming_time_per_weld_s":300,"spot_weld_time_s":0.96,"weld_heads":1}$jsonb$::jsonb, 0.1::numeric),
  ($str$part_assembly_robotic_spot_welding$str$, $str$PerformArc 125 (Panasonic- 60'' Turntable)$str$, $jsonb${"source":"memory/Part Assembly/Machine/robotic_spot_weld_machines.csv","gun_clean_time_per_arc_s":0,"gun_placement_time_s":2,"programming_time_per_weld_s":300,"spot_weld_time_s":0.96,"weld_heads":1}$jsonb$::jsonb, 0.1::numeric),
  ($str$part_assembly_robotic_spot_welding$str$, $str$PerformArc 150 (Panasonic- Servo Turntable)$str$, $jsonb${"source":"memory/Part Assembly/Machine/robotic_spot_weld_machines.csv","gun_clean_time_per_arc_s":0,"gun_placement_time_s":2,"programming_time_per_weld_s":300,"spot_weld_time_s":0.96,"weld_heads":1}$jsonb$::jsonb, 0.1::numeric),
  ($str$part_assembly_robotic_spot_welding$str$, $str$PerformArc 52 (Panasonic)$str$, $jsonb${"source":"memory/Part Assembly/Machine/robotic_spot_weld_machines.csv","gun_clean_time_per_arc_s":0,"gun_placement_time_s":2,"programming_time_per_weld_s":300,"spot_weld_time_s":0.96,"weld_heads":1}$jsonb$::jsonb, 0.1::numeric),
  ($str$laser_seam_welding$str$, $str$Default$str$, $jsonb${"index_time_s":15,"index_time_unit":"memory gives no unit; read as seconds, as its Load Time (30 s) and Unload Time (15 s)"}$jsonb$::jsonb, NULL::numeric),
  ($str$wire_brushing$str$, $str$default$str$, $jsonb${"wire_brushing_speed_mm_per_s":5}$jsonb$::jsonb, NULL::numeric)
) AS v(machine_class, machine_name, specs, operators)
WHERE m.process_group = $str$Part Assembly$str$ AND m.location = 'USA' AND m.machine_class = v.machine_class AND m.machine_name = v.machine_name;

DO $part_assembly_machines$
DECLARE
  cols text; sel text; r record; src_id uuid; n integer := 0; missing text[] := '{}';
BEGIN
  SELECT
    string_agg(quote_ident(c.column_name), ', ' ORDER BY c.ordinal_position),
    string_agg(
      CASE c.column_name
        WHEN 'location'                                THEN '$5'
        WHEN 'country_code'                            THEN '$6'
        WHEN 'direct_overhead_rate'                    THEN '$2'
        WHEN 'indirect_overhead_rate'                  THEN '$3'
        WHEN 'benchmark_direct_overhead_rate_usd_hr'   THEN '$2'
        WHEN 'benchmark_indirect_overhead_rate_usd_hr' THEN '$3'
        WHEN 'total_machine_hour_rate'                 THEN 'ROUND(($2 + $3)::numeric, 2)'
        WHEN 'mhr_usd_per_hour'                        THEN 'ROUND(($2 + $3)::numeric, 2)'
        WHEN 'usd_labor_rate_per_hr'                   THEN '$4'
        WHEN 'usd_lhr_total'                           THEN '$4'
        WHEN 'benchmark_labor_rate_usd_hr'             THEN '$4'
        WHEN 'benchmark_source_key'                    THEN '$7'
        WHEN 'id'                                      THEN 'gen_random_uuid()'
        WHEN 'created_at'                              THEN 'now()'
        WHEN 'updated_at'                              THEN 'now()'
        ELSE 'src.' || quote_ident(c.column_name)
      END, ', ' ORDER BY c.ordinal_position
    )
  INTO cols, sel
  FROM information_schema.columns c
  WHERE c.table_schema = 'public' AND c.table_name = 'mhr_records' AND c.is_generated = 'NEVER';

  -- (location, country, machine class, machine name, labour, direct overhead, indirect overhead, source key), USD/hr
  FOR r IN SELECT * FROM (VALUES
    ($str$India$str$, $str$IN$str$, $str$bevel_cutting$str$, $str$default$str$, 1.65, 0.3, 1.27, $str$Bevel Cutting:default:India$str$),
    ($str$India$str$, $str$IN$str$, $str$finish_grinding$str$, $str$default$str$, 1.65, 0.3, 1.27, $str$Finish Grinding:default:India$str$),
    ($str$India$str$, $str$IN$str$, $str$grinding$str$, $str$default$str$, 1.65, 0.3, 1.27, $str$Grinding:default:India$str$),
    ($str$India$str$, $str$IN$str$, $str$laser_seam_welding$str$, $str$Default$str$, 3.52, 17.04, 4.92, $str$Laser Seam Welding:Default:India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_manual_mig_welding$str$, $str$C240 (ESAB- 20A to 220A)$str$, 3.52, 1.4, 1.33, $str$Manual MIG Welding:C240 (ESAB- 20A to 220A):India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_manual_mig_welding$str$, $str$C280 (ESAB- 30A to 280A)$str$, 3.52, 1.4, 1.17, $str$Manual MIG Welding:C280 (ESAB- 30A to 280A):India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_manual_mig_welding$str$, $str$C420 (ESAB- 50A to 420A)$str$, 3.52, 1.41, 1.21, $str$Manual MIG Welding:C420 (ESAB- 50A to 420A):India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_manual_mig_welding$str$, $str$Default Mig Weld$str$, 3.52, 1.4, 1.21, $str$Manual MIG Welding:Default Mig Weld:India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_manual_mig_welding$str$, $str$Deltaweld 653 (Miller)$str$, 3.52, 1.42, 1.29, $str$Manual MIG Welding:Deltaweld 653 (Miller):India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_manual_spot_welding$str$, $str$Default Spot Weld$str$, 3.52, 1.42, 1.29, $str$Manual Spot Welding:Default Spot Weld:India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_manual_spot_welding$str$, $str$LMSW (Miller- 152mm tongs)$str$, 3.52, 1.27, 1.27, $str$Manual Spot Welding:LMSW (Miller- 152mm tongs):India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_manual_spot_welding$str$, $str$MSW (Miller- 152 mm tongs)$str$, 3.52, 1.27, 1.27, $str$Manual Spot Welding:MSW (Miller- 152 mm tongs):India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_manual_spot_welding$str$, $str$SSW (Miller- 152 mm tongs)$str$, 3.52, 4.47, 1.27, $str$Manual Spot Welding:SSW (Miller- 152 mm tongs):India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_manual_spot_welding$str$, $str$SSW (Miller- 305 mm tongs)$str$, 3.52, 1.5, 1.27, $str$Manual Spot Welding:SSW (Miller- 305 mm tongs):India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_robotic_mig_welding$str$, $str$Default Robotic Mig$str$, 2.75, 6.09, 2.22, $str$Robotic MIG Welding:Default Robotic Mig:India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_robotic_mig_welding$str$, $str$Pro System 2000 (Pro-Robots)$str$, 2.75, 6.09, 2.22, $str$Robotic MIG Welding:Pro System 2000 (Pro-Robots):India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_robotic_mig_welding$str$, $str$Pro System 3000 (Pro-Robots)$str$, 2.75, 6.09, 2.22, $str$Robotic MIG Welding:Pro System 3000 (Pro-Robots):India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_robotic_mig_welding$str$, $str$Pro Systen 1200$str$, 2.75, 6.09, 2.22, $str$Robotic MIG Welding:Pro Systen 1200:India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_robotic_mig_welding$str$, $str$Twin Station (ICS Robotics)$str$, 2.75, 6.09, 2.22, $str$Robotic MIG Welding:Twin Station (ICS Robotics):India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_robotic_spot_welding$str$, $str$Default Robotic Spot$str$, 2.75, 6.09, 2.22, $str$Robotic Spot Welding:Default Robotic Spot:India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_robotic_spot_welding$str$, $str$PerformArc 100 (Pansonic- 60'' Turntable)$str$, 2.75, 6.09, 2.21, $str$Robotic Spot Welding:PerformArc 100 (Pansonic- 60'' Turntable):India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_robotic_spot_welding$str$, $str$PerformArc 125 (Panasonic- 60'' Turntable)$str$, 2.75, 6.09, 2.21, $str$Robotic Spot Welding:PerformArc 125 (Panasonic- 60'' Turntable):India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_robotic_spot_welding$str$, $str$PerformArc 150 (Panasonic- Servo Turntable)$str$, 2.75, 6.09, 2.22, $str$Robotic Spot Welding:PerformArc 150 (Panasonic- Servo Turntable):India$str$),
    ($str$India$str$, $str$IN$str$, $str$part_assembly_robotic_spot_welding$str$, $str$PerformArc 52 (Panasonic)$str$, 2.75, 6.09, 2.22, $str$Robotic Spot Welding:PerformArc 52 (Panasonic):India$str$),
    ($str$India$str$, $str$IN$str$, $str$wire_brushing$str$, $str$default$str$, 1.65, 0.3, 1.27, $str$Wire Brushing:default:India$str$)
  ) AS v(location, country, machine_class, machine_name, labor, direct, indirect, source_key)
  LOOP
    SELECT id INTO src_id FROM mhr_records
    WHERE process_group = $str$Part Assembly$str$ AND location = 'USA' AND machine_class = r.machine_class AND machine_name = r.machine_name
    LIMIT 1;
    IF src_id IS NULL THEN
      missing := array_append(missing, r.machine_class || ':' || r.machine_name);
      CONTINUE;
    END IF;
    IF EXISTS (SELECT 1 FROM mhr_records m WHERE m.location = r.location AND m.machine_class = r.machine_class AND m.machine_name = r.machine_name) THEN
      CONTINUE;
    END IF;
    EXECUTE format('INSERT INTO mhr_records (%s) SELECT %s FROM mhr_records src WHERE src.id = $1', cols, sel)
      USING src_id, r.direct, r.indirect, r.labor, r.location, r.country, r.source_key;
    n := n + 1;
  END LOOP;

  RAISE NOTICE '% twins inserted: %', $str$Part Assembly$str$, n;
  IF array_length(missing, 1) > 0 THEN
    RAISE NOTICE '% twins with no USA row (not inserted): %', $str$Part Assembly$str$, missing;
  END IF;
END $part_assembly_machines$;

DO $part_assembly_check$
DECLARE bare text[];
BEGIN
  SELECT array_agg(location || ': ' || machine_class || ' ' || machine_name ORDER BY location, machine_class, machine_name) INTO bare FROM mhr_records
   WHERE process_group = $str$Part Assembly$str$ AND machine_class LIKE 'part_assembly_%' AND NOT COALESCE(specs ? 'gun_placement_time_s', false);
  IF bare IS NOT NULL THEN RAISE EXCEPTION 'Part Assembly welders still without the specs their calculators read: %', bare; END IF;
  SELECT array_agg(location || ': ' || machine_name ORDER BY location, machine_name) INTO bare FROM mhr_records
   WHERE machine_class IN ('part_assembly_manual_mig_welding', 'part_assembly_robotic_mig_welding')
     AND NOT (COALESCE(specs ? 'wire_feed_rate_mm_s', false) AND COALESCE(specs ? 'wire_diameter_mm', false));
  IF bare IS NOT NULL THEN RAISE EXCEPTION 'Part Assembly MIG welders without a wire feed rate and diameter: %', bare; END IF;
  SELECT array_agg(location || ': ' || machine_name ORDER BY location, machine_name) INTO bare FROM mhr_records
   WHERE machine_class = 'part_assembly_robotic_spot_welding' AND COALESCE(operators, 0) = 0;
  IF bare IS NOT NULL THEN RAISE EXCEPTION 'Robotic spot welders still with no crew: %', bare; END IF;
END $part_assembly_check$;

NOTIFY pgrst, 'reload schema';
